import heapq


def dependency(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices.append([-1] + versions)

    best = None
    best_vector = None
    for vector in product(*choices):
        selected = {name: version for name, version in zip(names, vector) if version != -1}
        rows = {name: next(row for row in packages[name] if row["version"] == version)
                for name, version in selected.items()}
        edges = {name: [] for name in selected}
        valid = True
        for name, bounds in data["roots"].items():
            if name not in selected or not bounds[0] <= selected[name] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        reachable = set(data["roots"])
        todo = list(reachable)
        while todo and valid:
            name = todo.pop()
            if name not in selected:
                valid = False
                break
            for dep in rows[name].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                edges[name].append(other)
                if other not in selected or not dep["min"] <= selected[other] <= dep["max"]:
                    valid = False
                    break
                if other not in reachable:
                    reachable.add(other)
                    todo.append(other)
        if not valid or reachable != set(selected):
            continue
        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(child) for child in edges[name]):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(visit(name) for name in selected):
            continue
        if best is None or (vector > best_vector if maximize else vector < best_vector):
            best, best_vector = selected, vector
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)
    balances = dict(data.get("opening", {}))
    def rounded(num, den):
        if data["rounding"] == "half_up":
            return (num + den // 2) // den
        return num // den
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def quota(data):
    jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({j["id"] for j in jobs}):
        return {"error": "impossible"}
    best_ids = None
    best_value = None
    quotas = data.get("quotas", {})
    k = data["k"]
    for subset in combinations(jobs, k):
        ids = tuple(sorted(j["id"] for j in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for j in subset:
            counts[j["group"]] = counts.get(j["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i]["start"] < ordered[i-1]["end"] for i in range(1, len(ordered))):
            continue
        value = sum(j["value"] for j in subset)
        if best_ids is None or value > best_value or (value == best_value and ids > best_ids):
            best_ids, best_value = ids, value
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def routes(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    node_mask = [sum(1 << i for i, req in enumerate(required) if req == node)
                 for node in range(data["n"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start, source = data["start"], data["source"]
    initial = (source, node_mask[source], data["coupons"])
    dist = {initial: start}
    queue = [(start, *initial)]
    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], left)]
            if left:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), left - 1))
            for duration, remaining in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = (edge["v"], mask | node_mask[edge["v"]], remaining)
                if arrival < dist.get(nxt, float("inf")):
                    dist[nxt] = arrival
                    heapq.heappush(queue, (arrival, *nxt))
    return {"arrival": None}


